# SPDX-License-Identifier: MIT
# What the web panel reads and sets on the board, from its description (mpy_board): its analog
# inputs (A0 to A5 on the STM32MP157C-DK2, A0 and A1 on the STM32MP135F-DK), two of its LEDs and a
# PWM output, whatever serves them (the Cortex-M4, Linux's drivers, a GPIO line); and the addresses
# a browser reaches the board at. In the LVGL MPY Studio simulator, made-up values.

import time

try:
    import machine
    import mpy_board

    HARDWARE = hasattr(machine, "ADC")
except ImportError:
    HARDWARE = False

PWM_HZ = 1000
LED_ORDER = ("red", "green", "orange", "blue")


def _label(pin):
    # The name a user knows a pin by: the board's alias ("A0", "D6"), else its connector pin.
    described = mpy_board.describe()
    for alias, name in sorted(described.get("aliases", {}).items()):
        if name == pin:
            return alias
    connector = described.get("connector", {})
    for number, name in connector.get("pins", {}).items():
        if name == pin:
            return "pin %s" % number
    return pin


class _Led:
    # One LED of the description: a GPIO line (by name, or ["chip", line]), the Cortex-M4's, or
    # Linux's LED class.
    def __init__(self, name, spec):
        self.name = name
        self._spec = spec
        self._pin = None
        if "pin" in spec:
            line = spec["pin"]
            line = tuple(line) if isinstance(line, list) else line
            self._pin = machine.Pin(line, machine.Pin.OUT, value=1 if spec.get("active_low") else 0)

    def set(self, on):
        if self._pin is not None:
            self._pin.value((0 if on else 1) if self._spec.get("active_low") else (1 if on else 0))
        elif self._spec.get("mcu"):
            import mpy_m4

            mpy_m4.led(on)
        elif "sysfs" in self._spec:
            root = "/sys/class/leds/%s/" % self._spec["sysfs"]
            with open(root + "trigger", "w") as f:
                f.write("none" if on else "heartbeat")
            if on:
                with open(root + "brightness", "w") as f:
                    f.write("1")


class Board:
    def __init__(self):
        described = mpy_board.describe()
        adc = described.get("adc", {})
        pins = list(adc.get("pins", []))
        aliased = sorted((alias, name) for alias, name in described.get("aliases", {}).items()
                         if name in pins and alias.startswith("A"))
        inputs = aliased or [(name, name) for name in sorted(pins)]
        self.names = [label for label, name in inputs]
        self.range_v = adc.get("range_uv", 2500000) / 1e6
        self._adcs = [machine.ADC(name) for label, name in inputs]
        leds = described.get("leds", {})
        chosen = [name for name in LED_ORDER if name in leds][:2]
        self.leds = [_Led(name, leds[name]) for name in chosen]
        outputs = sorted(described.get("pwm", {})) if hasattr(machine, "PWM") else []
        self._pwm_pin = outputs[0] if outputs else None
        self.pwm_name = _label(self._pwm_pin) if self._pwm_pin else ""
        self.board = described.get("board", "This board")
        self._pwm = None

    def inputs(self):
        return [adc.read_uv() / 1000000 for adc in self._adcs]

    def led(self, index, on):
        self.leds[index].set(on)

    def duty(self, percent):
        if self._pwm_pin is None:
            raise OSError(95, "no PWM on this board")
        if self._pwm is None:
            self._pwm = machine.PWM(self._pwm_pin, freq=PWM_HZ, duty_u16=0)
        self._pwm.duty_u16(percent * 65535 // 100)

    def addresses(self):
        found = []
        try:
            import mpy_wifi

            ip = mpy_wifi.status().get("ip")
            if ip:
                found.append(("Wi-Fi", ip))
        except (ImportError, OSError):
            pass
        found.append(("USB", "192.168.7.1"))
        return found


class _SimulatedLed:
    def __init__(self, name):
        self.name = name


class Simulated:
    names = ["A0", "A1", "A2", "A3", "A4", "A5"]
    range_v = 2.5
    leds = [_SimulatedLed("red"), _SimulatedLed("orange")]
    pwm_name = "D6"
    board = "STM32MP157C-DK2"

    def inputs(self):
        t = time.ticks_ms() / 1000
        return [round(1.25 + 1.0 * ((t * (i + 1) / 7) % 1 - 0.5), 3) for i in range(6)]

    def led(self, index, on):
        pass

    def duty(self, percent):
        pass

    def addresses(self):
        return [("Wi-Fi", "192.168.1.50")]


board = Board() if HARDWARE else Simulated()

# SPDX-License-Identifier: MIT
# A small HTTP server in MicroPython, polled from the GUI's timer: it never blocks the screen.
# One page for the browser (PAGE, with the board's names put in by Server(names=...)), and two JSON
# calls: /api/state and /api/set. Every request needs the
# PIN shown on the board's screen: anyone on the network can reach the board, and this keeps a
# passer-by out, no more (plain HTTP, no accounts).

import json
import socket

PAGE = """<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Board</title>
<style>
body{font-family:system-ui,sans-serif;background:#121820;color:#fff;margin:0;padding:16px;max-width:520px}
h1{font-size:24px;margin:0 0 12px}.card{background:#1e2633;border-radius:12px;padding:14px;margin-bottom:12px}
.row{display:flex;align-items:center;justify-content:space-between;margin:8px 0}
.bar{height:10px;background:#2a3444;border-radius:5px;flex:1;margin:0 10px}
.fill{height:10px;background:#4cc38a;border-radius:5px}
button{font-size:16px;border:0;border-radius:8px;padding:10px 16px;background:#2a3444;color:#fff}
button.on{background:#e0742f}input[type=range]{width:100%}
input[type=text]{width:100%;box-sizing:border-box;font-size:16px;padding:10px;border-radius:8px;border:0}
small{color:#8fa0b5}
</style></head><body>
<h1>{board}</h1>
<div class="card"><small>ANALOG INPUTS</small><div id="inputs"></div></div>
<div class="card"><small>OUTPUTS</small>
<div class="row">{led1} LED<button id="led1" onclick="toggle('led1')">off</button></div>
<div class="row">{led2} LED<button id="led2" onclick="toggle('led2')">off</button></div>
<div>PWM on {pwm}, 1 kHz: <b id="dutyv">0</b>%<input id="duty" type="range" min="0" max="100" value="0"
 onchange="set('duty',this.value)"></div></div>
<div class="card"><small>A MESSAGE FOR THE BOARD'S SCREEN</small>
<input id="msg" type="text" maxlength="60" placeholder="Hello from my phone">
<p><button onclick="set('message',document.getElementById('msg').value)">Send</button></p></div>
<script>
const k=new URLSearchParams(location.search).get('k')||'';let state={};
function set(what,value){fetch('/api/set?k='+k+'&'+what+'='+encodeURIComponent(value)).then(r=>r.json()).then(show)}
function toggle(what){set(what,state[what]?0:1)}
function show(s){state=s;let h='';s.inputs.forEach((v,i)=>{h+='<div class="row">'+s.names[i]+'<div class="bar"><div class="fill" style="width:'+
Math.min(100,v/s.range*100)+'%"></div></div>'+v.toFixed(3)+' V</div>'});document.getElementById('inputs').innerHTML=h;
for(const w of ['led1','led2']){const b=document.getElementById(w);b.className=s[w]?'on':'';b.textContent=s[w]?'on':'off'}
document.getElementById('dutyv').textContent=s.duty}
function poll(){fetch('/api/state?k='+k).then(r=>r.json()).then(show).finally(()=>setTimeout(poll,500))}
poll()
</script></body></html>"""

ASK_PIN = """<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PIN</title></head><body style="font-family:system-ui;background:#121820;color:#fff;padding:24px">
<form>The PIN on the board's screen: <input name="k" inputmode="numeric" size="6"> <button>Open</button>
</form></body></html>"""


def _unquote(text):
    text = text.replace("+", " ")
    parts = text.split("%")
    out = bytearray(parts[0].encode())
    for part in parts[1:]:
        try:
            out.append(int(part[:2], 16))
            out.extend(part[2:].encode())
        except ValueError:
            out.extend(("%" + part).encode())
    return out.decode()


def _parameters(query):
    found = {}
    for item in query.split("&"):
        if item:
            key, _, value = item.partition("=")
            found[_unquote(key)] = _unquote(value)
    return found


class Server:
    # handle(path, parameters, client) -> (status, content type, body); called only with the PIN.

    def __init__(self, port, pin, handle, names=None):
        self._page = PAGE
        for key, value in (names or {}).items():
            self._page = self._page.replace("{%s}" % key, value)
        self.port = port
        self.pin = pin
        self._handle = handle
        self._socket = None

    def start(self):
        if self._socket:
            return
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.setsockopt(socket.SOL_SOCKET, 2, 1)  # SO_REUSEADDR: restart without waiting
        listener.bind(socket.getaddrinfo("0.0.0.0", self.port)[0][-1])
        listener.listen(4)
        listener.setblocking(False)
        self._socket = listener

    def stop(self):
        if self._socket:
            self._socket.close()
            self._socket = None

    def running(self):
        return self._socket is not None

    def poll(self):
        # The requests waiting, each answered at once (a few milliseconds).
        for _ in range(4):
            try:
                client, address = self._socket.accept()
            except (OSError, AttributeError):
                return
            try:
                self._serve(client, address)
            except OSError:
                pass
            finally:
                client.close()

    def _serve(self, client, address):
        client.settimeout(0.5)
        request = b""
        while b"\r\n\r\n" not in request and len(request) < 4096:
            part = client.recv(1024)
            if not part:
                break
            request += part
        line = request.split(b"\r\n", 1)[0].decode()
        method, _, rest = line.partition(" ")
        target = rest.split(" ", 1)[0]
        path, _, query = target.partition("?")
        parameters = _parameters(query)
        who = ".".join(str(b) for b in address[4:8]) if len(address) >= 8 else "?"
        if parameters.get("k") != self.pin:
            status, kind, body = (200, "text/html", ASK_PIN) if path == "/" else (403, "text/plain", "PIN")
        elif path == "/":
            status, kind, body = 200, "text/html", self._page
        else:
            status, kind, body = self._handle(path, parameters, who)
            if not isinstance(body, str):
                body, kind = json.dumps(body), "application/json"
        data = body.encode()
        head = "HTTP/1.0 %d OK\r\nContent-Type: %s; charset=utf-8\r\nContent-Length: %d\r\n" \
               "Cache-Control: no-store\r\nConnection: close\r\n\r\n" % (status, kind, len(data))
        client.write(head.encode() + data)

# SPDX-License-Identifier: MIT
# Web Panel: the board serves a page to the browsers of its network (a QR code to open it, a PIN to
# use it); what they read and set goes through machine on the board, and the screen shows it live.
# The inputs, LEDs and PWM are the board's own, from its description (board_io).

import os
import time

import lvgl as lv

from board_io import HARDWARE, board
from server import Server

PORT = 8080

_ui = None
_server = None
_qr = None
_state = {"inputs": [0.0] * len(board.names), "names": board.names, "range": board.range_v, "led1": 0,
          "led2": 0, "duty": 0, "message": ""}
_log = []
_ticks = 0


def _clock():
    t = time.localtime()
    return "%02d:%02d:%02d" % (t[3], t[4], t[5])


def _note(who, what):
    _log.insert(0, "%s  %-15s %s" % (_clock(), who, what))
    del _log[8:]
    _ui.log.set_text("\n".join(_log))


def _show_outputs():
    leds = "    ".join("%s LED %s" % (_title(led.name), "on" if _state["led%d" % (i + 1)] else "off")
                       for i, led in enumerate(board.leds))
    _ui.outputs.set_text("%s%sPWM on %s %d%%" % (leds, "\n" if _small() else "    ", board.pwm_name, _state["duty"]))


def _title(name):
    return name[:1].upper() + name[1:]


def _small():
    return lv.display_get_default().get_vertical_resolution() < 400


def handle(path, parameters, who):
    # From the server, with the right PIN: /api/state reads, /api/set changes one thing.
    if path == "/api/set":
        try:
            for i, led in enumerate(board.leds):
                key = "led%d" % (i + 1)
                if key in parameters:
                    _state[key] = 1 if parameters[key] == "1" else 0
                    board.led(i, _state[key])
                    _note(who, "%s LED %s" % (led.name, "on" if _state[key] else "off"))
            if "duty" in parameters:
                _state["duty"] = max(0, min(100, int(parameters["duty"])))
                board.duty(_state["duty"])
                _note(who, "PWM %d%%" % _state["duty"])
            elif "message" in parameters:
                _state["message"] = parameters["message"][:60]
                _ui.message.set_text(_state["message"])
                _note(who, "message")
        except (OSError, ValueError) as error:
            _note(who, "error: %s" % error)
            return 500, "text/plain", str(error)
        _show_outputs()
        return 200, "", _state
    if path == "/api/state":
        return 200, "", _state
    return 404, "text/plain", "not found"


def _read_inputs():
    try:
        _state["inputs"] = [round(v, 3) for v in board.inputs()]
    except OSError as error:
        _ui.inputs.set_text("Inputs: %s" % error)
        return
    shown = ["%s %.2f V" % (name, v) for name, v in zip(board.names, _state["inputs"])]
    _ui.inputs.set_text("   ".join(shown[:3]) + ("\n" + "   ".join(shown[3:]) if shown[3:] else ""))


def _show_address():
    name, ip = board.addresses()[0]
    url = "http://%s:%d/?k=%s" % (ip, PORT, _server.pin)
    _qr.update(url, len(url))
    _ui.url.set_text("%s\n%s:%d" % (name, ip, PORT))


def tick():
    # Every 20 ms: the browsers' requests; every 250 ms the inputs; every 10 s the address.
    global _ticks
    _ticks += 1
    if _server.running():
        _server.poll()
    if _ticks % 12 == 0:
        _read_inputs()
    if _ticks % 500 == 0:
        _show_address()


def serve_changed(switch):
    on = switch.has_state(lv.STATE.CHECKED)
    if not HARDWARE:
        _ui.serve_label.set_text("Simulator")
        return
    try:
        if on:
            _server.start()
        else:
            _server.stop()
        _ui.serve_label.set_text("Serving" if on else "Stopped")
    except OSError as error:
        _ui.serve_label.set_text("Error %s" % error)


def start(ui):
    global _ui, _server, _qr
    _ui = ui
    lv.screen_active().set_style_bg_color(lv.color_hex(0x121820), 0)
    pin = "%04d" % (int.from_bytes(os.urandom(2), "little") % 10000)
    names = {"board": board.board, "pwm": board.pwm_name}
    for i, led in enumerate(board.leds):
        names["led%d" % (i + 1)] = _title(led.name)
    _server = Server(PORT, pin, handle, names)
    _qr = lv.qrcode(ui.qr_panel)
    _qr.set_size(108 if _small() else 210)
    _qr.set_dark_color(lv.color_hex(0x000000))
    _qr.set_light_color(lv.color_hex(0xFFFFFF))
    _qr.set_pos(14 if _small() else 20, 6 if _small() else 20)
    _qr.set_style_border_color(lv.color_hex(0xFFFFFF), 0)
    _qr.set_style_border_width(6, 0)
    ui.pin.set_text("PIN " + pin)
    _show_address()
    _show_outputs()
    _ui.log.set_text("Scan the code with a phone on the same network,\nor open the address.")
    if HARDWARE:
        try:
            _server.start()
        except OSError as error:
            ui.serve_label.set_text("Error %s" % error)
    else:
        ui.serve_label.set_text("Simulator")
